import React from 'react';

const images = [
  { src: '/assets/work-1.jpg', alt: 'Bureaux après entretien' },
  { src: '/assets/work-2.jpg', alt: 'Vitrines de commerce nettoyées' },
  { src: '/assets/work-3.jpg', alt: 'Copropriété — parties communes' },
  { src: '/assets/work-4.jpg', alt: 'Fins de chantier — remise en état' },
  { src: '/assets/work-5.jpg', alt: 'Location courte durée — ménage complet' },
  { src: '/assets/work-6.jpg', alt: 'Cabinet médical — désinfection' },
];

export default function Realisations() {
  return (
    <section>
      <h2>Nos réalisations</h2>
      <p className="hint">Remplacez par vos photos réelles (dossier <code>public/assets</code>).</p>
      <div className="gallery">
        {images.map((im)=>(
          <figure key={im.src}>
            <img src={im.src} alt={im.alt} />
            <figcaption className="small" style={{padding:'8px 10px'}}>{im.alt}</figcaption>
          </figure>
        ))}
      </div>
    </section>
  );
}
